p='quillmark/markdown.py'
s=open(p).read()
i=s.index("def to_html")
new='''class _Parser:
    """Line-by-line block parser; each block type has a handler."""

    def __init__(self) -> None:
        self.blocks: list[str] = []
        self.paragraph: list[str] = []
        self.list_tag: str | None = None
        self.list_items: list[str] = []
        self.in_fence = False
        self.fence_lang = ""
        self.fence_lines: list[str] = []

    def parse(self, source: str) -> str:
        for line in source.splitlines():
            self.feed(line)
        if self.in_fence:
            self.flush_fence()
        self.flush_text()
        return "\\n".join(self.blocks) + ("\\n" if self.blocks else "")

    def feed(self, line: str) -> None:
        if self.in_fence:
            self.fence_body(line)
        elif _FENCE.match(line):
            self.fence_open(line)
        elif not line.strip():
            self.flush_text()
        elif _HEADING.match(line):
            self.heading(line)
        elif _ULIST.match(line) or _OLIST.match(line):
            self.list_item(line)
        else:
            self.text(line)

    def flush_text(self) -> None:
        self.flush_paragraph()
        self.flush_list()

    # -- headings -----------------------------------------------------
    def heading(self, line: str) -> None:
        self.flush_text()
        match = _HEADING.match(line)
        level = len(match.group(1))
        self.blocks.append(f"<h{level}>{inline(match.group(2))}</h{level}>")

    # -- fenced code --------------------------------------------------
    def fence_open(self, line: str) -> None:
        self.flush_text()
        self.in_fence = True
        self.fence_lang = _FENCE.match(line).group(1)

    def fence_body(self, line: str) -> None:
        if line.strip() == "```":
            self.flush_fence()
        else:
            self.fence_lines.append(line)

    def flush_fence(self) -> None:
        attr = f' class="language-{self.fence_lang}"' if self.fence_lang else ""
        code = html.escape("\\n".join(self.fence_lines), quote=False)
        self.blocks.append(f"<pre><code{attr}>{code}</code></pre>")
        self.fence_lines.clear()
        self.in_fence = False

    # -- lists --------------------------------------------------------
    def list_item(self, line: str) -> None:
        self.flush_paragraph()
        for pattern, tag in ((_ULIST, "ul"), (_OLIST, "ol")):
            item = pattern.match(line)
            if item:
                if self.list_tag != tag:
                    self.flush_list()
                    self.list_tag = tag
                self.list_items.append(item.group(1))
                return

    def flush_list(self) -> None:
        if self.list_tag:
            tag = self.list_tag
            items = "".join(f"<li>{inline(item)}</li>" for item in self.list_items)
            self.blocks.append(f"<{tag}>{items}</{tag}>")
            self.list_items.clear()
            self.list_tag = None

    # -- paragraphs ---------------------------------------------------
    def text(self, line: str) -> None:
        if self.list_tag and line.startswith((" ", "\\t")):
            self.list_items[-1] += " " + line.strip()
            return
        self.flush_list()
        self.paragraph.append(line.strip())

    def flush_paragraph(self) -> None:
        if self.paragraph:
            self.blocks.append(f"<p>{inline(' '.join(self.paragraph))}</p>")
            self.paragraph.clear()


def to_html(source: str) -> str:
    return _Parser().parse(source)
'''
open(p,'w').write(s[:i]+new)
